contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to, uint256 value) public payable {
        require(to != address(0));
        // Observe balances before
        uint256 beforeFrom = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeTo = c.balanceOf(to); if (__ESBMC_reverted()) return;

        // Attempt transfer and record whether it reverted
        bool reverted;
        c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe balances after
        uint256 afterFrom = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterTo = c.balanceOf(to); if (__ESBMC_reverted()) return;

        // If the call did not revert, the combined balance of the two addresses must be conserved
        // If it reverted, we make no requirement about balances changing.
        assert(reverted || (afterFrom + afterTo == beforeFrom + beforeTo));
    }
    receive() external payable {}
}

